#include <stdio.h>

void show(int value)
{
    if (value == 0) {
        puts("empty");
        return;
    }
    puts("ready");
}

int main(void)
{
    show(0);
    show(2);
    return 0;
}

#include <stdio.h>

void split(int total, int *hours, int *minutes)
{
    *hours = total / 60;
    *minutes = total % 60;
}

int main(void)
{
    int h, m;
    split(125, &h, &m);
    printf("%d %d\n", h, m);
    return 0;
}

